def check(candidate) -> bool:
    try:
        if not isinstance(candidate, (list, tuple)):
            return False
        if len(candidate) != 12:
            return False
        S = []
        for x in candidate:
            if isinstance(x, bool) or not isinstance(x, int):
                return False
            if x < 0 or x > 115:
                return False
            S.append(x)
        if len(set(S)) != 12:
            return False
        S = sorted(S)
        # Sidon check: all sums a+b with a<=b distinct
        sums2 = set()
        for i in range(12):
            for j in range(i, 12):
                s = S[i] + S[j]
                if s in sums2:
                    return False
                sums2.add(s)
        # triple sums
        sums3 = set()
        for s in sums2:
            for a in S:
                sums3.add(s + a)
        for n in range(116):
            if n not in sums3:
                return False
        return True
    except Exception:
        return False
